compose.resources {
    publicResClass = true
    generateResClass = always
    packageOfResClass = "vvinampapp.composeapp.generated.resources"
}

// Workaround: Compose Multiplatform's Android task pipeline doesn't include
// commonMain resources when using com.android.kotlin.multiplatform.library
// plugin (AGP 9.0). Expose the prepared commonMain resources at a known
// location so the consuming app (`presentation`) can include them as assets.
val copyComposeResourcesToAndroidAssets by tasks.registering(Copy::class) {
    dependsOn("prepareComposeResourcesTaskForCommonMain")
    from(layout.buildDirectory.dir("generated/compose/resourceGenerator/preparedResources/commonMain"))
    into(layout.buildDirectory.dir("generated/composeResourcesForAndroid/assets"))
}

plugins {
    alias(libs.plugins.android.application)
    alias(libs.plugins.ksp)
    alias(libs.plugins.serialization)
    alias(libs.plugins.compose)
}

android {
    namespace = "com.example.presentation"
    compileSdk = libs.versions.compileSdk.get().toInt()

    defaultConfig {
        applicationId = "com.example.presentation"
        minSdk = libs.versions.minSdk.get().toInt()
        targetSdk = compileSdk
        versionCode = 1
        versionName = "1.0"

        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    }

    buildTypes {
        release {
            isMinifyEnabled = false
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro"
            )
        }
    }

    flavorDimensions += listOf("environment")

    productFlavors {
        create("prod") {
            dimension = "environment"
            applicationIdSuffix = ".prod"
            isDefault = true
        }
        create("mock") {
            dimension = "environment"
            applicationIdSuffix = ".mock"
        }
    }
    buildFeatures {
        compose = true
    }

    composeOptions {
        kotlinCompilerExtensionVersion = libs.versions.kotlinGradlePlugin.get()
    }
}

kotlin {
    jvmToolchain(libs.versions.jdk.get().toInt())

    compilerOptions {
        freeCompilerArgs.addAll(listOf("-Xjvm-default=all"))
    }
}

dependencies {
    api(project(":data"))
    api(project(":composeApp"))
    testImplementation(project(":core-test"))
    debugImplementation(libs.chucker.debug)
    releaseImplementation(libs.chucker.release)

    // Kover Coverage (All Modules)
    kover(project(":data"))
    kover(project(":domain"))

    // Kotlin
    implementation(libs.kotlin.stdlib.jdk8)

    // AndroidX
    implementation(libs.appcompat)
    implementation(libs.lifecycle.viewmodel.ktx)

    // Extensions
    implementation(libs.core.ktx)
    implementation(libs.lifecycle.extensions)

    // okHttp
    implementation(libs.okhttp)
    implementation(libs.logging.interceptor)

    // GSON
    implementation(libs.gson)

    // Retrofit
    implementation(libs.retrofit)
    implementation(libs.converter.gson)

    // Room
    implementation(libs.room.runtime)
    ksp(libs.room.compiler)

    // Koin
    implementation(libs.koin.android)
    implementation(libs.koin.compose)

    // Coroutines
    // implementation(libs.kotlinx.coroutines.android)

    // Paging
    implementation(libs.paging.compose)

    // WorkManager
    implementation(libs.work.runtime.ktx)

    // Palette
    implementation(libs.palette)

    // Reorderable
    implementation(libs.reorderable)

    // Compose
    implementation(libs.accompanist.systemuicontroller)
    implementation(libs.wheel.picker.compose)

    // Coil
    implementation(libs.coil.compose)
    implementation(libs.coil.network.okhttp)

    //media3
    implementation(libs.bundles.media3)

    // Serialization
    implementation(libs.kotlinx.serialization.json)
}

