// Workaround: com.android.kotlin.multiplatform.library plugin doesn't package
// compose resources into the AAR's assets. Manually copy them.
val copyComposeResourcesToAndroidAssets by tasks.registering(Copy::class) {
    val prepareTask = tasks.named("prepareComposeResourcesTaskForAndroidMain")
    from(prepareTask.map { it.outputs.files })
    into(layout.buildDirectory.dir("generated/composeResourcesForAndroid/assets"))
}

androidComponents {
    onVariants { variant ->
        variant.sources.assets?.addGeneratedSourceDirectory(
            copyComposeResourcesToAndroidAssets,
            Copy::destinationDir
        )
    }
}

